def lift(transactions, x, y):
    sx = support(transactions, x)
    sy = support(transactions, y)
    sxy = support(transactions, set(x) | set(y))
    if sx == 0 or sy == 0:
        return 0.0
    conf = sxy / sx
    return round(conf / sy, 4)

