def find_paths(node, target, prefix, results):
    """从树中找以 target 结尾的所有路径（返回前缀）。"""
    for name, child in node.children.items():
        if name == target:
            results.append((list(prefix), child.count))
        find_paths(child, target, prefix + [name], results)

